import { runQpdf } from './qpdf';

/** Shrinks a PDF by recompressing its embedded images as JPEG at the given quality
 * and recompressing its internal streams — text and vector content are untouched. */
export async function compressPdf(file: File, jpegQuality: number): Promise<Blob> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const outBytes = await runQpdf(bytes, [
    '--optimize-images',
    `--jpeg-quality=${jpegQuality}`,
    '--compress-streams=y',
    '--recompress-flate',
    '--object-streams=generate',
    '--',
    '{in}',
    '{out}',
  ]);
  return new Blob([outBytes], { type: 'application/pdf' });
}
