import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Minimize2 } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import UploadBox from '@/components/tools/pdf-to-jpg/UploadBox';
import ProcessResult from '@/components/tools/pdf-security/ProcessResult';
import SetupGate from '@/components/tools/pdf-security/SetupGate';
import QualitySlider from '@/components/tools/image-converter/QualitySlider';
import { usePersistentState } from '@/hooks/usePersistentState';
import { formatBytes } from '@/lib/image/convert';
import { compressPdf } from '@/lib/pdf/compress';

const CompressPdf: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('compress-pdf:file', null);
  const [quality, setQuality] = usePersistentState<number>('compress-pdf:quality', 70);

  const [blob, setBlob] = useState<Blob | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setBlob(null);
    setError(null);
  }, [file, quality]);

  const canGenerate = !!file;

  const handleGenerate = () => {
    if (!file) return;
    setError(null);
    setIsProcessing(true);
    compressPdf(file, quality)
      .then((result) => {
        setBlob(result);
        setIsProcessing(false);
      })
      .catch((err: Error) => {
        setError(err.message || "Couldn't compress this PDF");
        setIsProcessing(false);
      });
  };

  const fileName = file ? `${file.name.replace(/\.pdf$/i, '') || 'document'}-compressed.pdf` : 'compressed.pdf';

  const delta = blob && file ? blob.size - file.size : 0;
  const pct = blob && file && file.size > 0 ? Math.round((delta / file.size) * 100) : 0;

  return (
    <ToolLayout
      title="Compress PDF"
      description="Shrink a PDF's file size by recompressing its embedded images — entirely in your browser, nothing is uploaded anywhere."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && <QualitySlider quality={quality} onChange={setQuality} />}

        <SetupGate>
          <ProcessResult
            hasFile={!!file}
            blob={blob}
            fileName={fileName}
            isProcessing={isProcessing}
            processingLabel="Compressing…"
            error={error}
            canGenerate={canGenerate}
            generateLabel="Compress PDF"
            generateIcon={<Minimize2 className="w-4 h-4" />}
            onGenerate={handleGenerate}
            summary={
              blob &&
              file && (
                <p className="text-sm font-medium text-foreground">
                  {formatBytes(file.size)} → {formatBytes(blob.size)}{' '}
                  <span className={delta <= 0 ? 'text-accent' : 'text-muted-foreground'}>
                    ({delta <= 0 ? '' : '+'}
                    {pct}%)
                  </span>
                </p>
              )
            }
          />
        </SetupGate>
      </div>
    </ToolLayout>
  );
};

export default CompressPdf;
